import { nextActions, type NextFacts } from '@/lib/next-actions-rules';
import { is, done } from '@/tests/check';
const now = Date.UTC(2026,10,10);
const options = { may: () => true, currency: 'usd', now };
const fields = ['failedPayments','monthlyMembers','formerMembers','courseNext','noWelcome'] as const;
const ids = ['failed_payments','yearly_switch','winback','course_next','welcome'];
const bad: unknown[] = [undefined,null,false,true,'0','86',[],{},NaN,Infinity,-Infinity,-1,0.01,Number.MAX_SAFE_INTEGER+1];
for (let i=0;i<fields.length;i++) for (let j=0;j<bad.length;j++) {
  const fact = { count:bad[j], at:now, from:'Course A', to:'Course B' };
  const v=nextActions({ [fields[i]]:fact } as NextFacts, options);
  is(`${fields[i]} malformed count ${j} is named unknown`, v.kind==='unknown'?v.unknown:v.kind, [ids[i]]);
}
for (let bits=0;bits<8;bits++) {
  const may=(p:string)=>({stats:!!(bits&1),draft:!!(bits&2),send:!!(bits&4)}[p]??false);
  for(let i=0;i<fields.length;i++) {
    const v=nextActions({ [fields[i]]:{count:null,at:now,from:'A',to:'B'} } as NextFacts,{...options,may});
    const allowed=!!(bits&1)&&!!(bits&(i===4?4:2));
    is(`permissions ${bits} field ${i} do not disclose forbidden missing counts`,v.kind,allowed?'unknown':'nothing');
  }
}
const facts:NextFacts={monthlyMembers:{count:2,monthly:{amount:1,currency:'usd'},at:now},formerMembers:{count:9,monthly:{amount:999999999,currency:'jpy'},at:now},courseNext:{count:10,from:'A',to:'B',at:now}};
let v=nextActions(facts,options);
is('other-currency amount never outranks known store-currency money',v.kind==='actions'?v.actions.map(a=>a.id):v.kind,['yearly_switch','course_next','winback']);
v=nextActions({...facts,failedPayments:{count:1,owed:null,at:now}},options);
is('owed first and cap retained with unknown amount',v.kind==='actions'?v.actions.map(a=>a.id):v.kind,['failed_payments','yearly_switch','course_next']);
const frozen=Object.freeze({noWelcome:Object.freeze({count:Number.MAX_SAFE_INTEGER,at:now})});
v=nextActions(frozen,options);
is('maximum safe count stays exact in plain words without changing facts',v.kind==='actions'?v.actions[0].words:'', '9,007,199,254,740,991 people joined your list and never got a welcome email.');
is('facts remain frozen and unchanged',frozen.noWelcome.count,Number.MAX_SAFE_INTEGER);
done();

